import{_ as a,o as i,c as t,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"13. Safety, Determinism, and Reviewability","description":"","frontmatter":{},"headers":[],"relativePath":"spec/13-safety.md","filePath":"spec/13-safety.md","lastUpdated":null}'),n={name:"spec/13-safety.md"};function o(s,e,l,c,d,m){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="_13-safety-determinism-and-reviewability" tabindex="-1">13. Safety, Determinism, and Reviewability <a class="header-anchor" href="#_13-safety-determinism-and-reviewability" aria-label="Permalink to &quot;13. Safety, Determinism, and Reviewability&quot;">​</a></h1><h2 id="_13-1-threat-model" tabindex="-1">13.1 Threat model <a class="header-anchor" href="#_13-1-threat-model" aria-label="Permalink to &quot;13.1 Threat model&quot;">​</a></h2><p>A user should be able to download an unfamiliar <code>.linnet</code> model definition and statically inspect/check it without granting arbitrary code execution.</p><h2 id="_13-2-forbidden-implicit-capabilities" tabindex="-1">13.2 Forbidden implicit capabilities <a class="header-anchor" href="#_13-2-forbidden-implicit-capabilities" aria-label="Permalink to &quot;13.2 Forbidden implicit capabilities&quot;">​</a></h2><p>Core Linnet source has no facilities for:</p><ul><li>filesystem access;</li><li>sockets/network access;</li><li>subprocess creation;</li><li>dynamic library loading;</li><li>environment-variable access;</li><li>host-language evaluation;</li><li>arbitrary native callbacks;</li><li>package installation scripts;</li><li>compile-time code execution from user packages.</li></ul><h2 id="_13-3-imports" tabindex="-1">13.3 Imports <a class="header-anchor" href="#_13-3-imports" aria-label="Permalink to &quot;13.3 Imports&quot;">​</a></h2><p>Imports resolve only through the package/module resolver and fixed package metadata. Source code cannot construct dynamic import paths from runtime values.</p><h2 id="_13-4-macros" tabindex="-1">13.4 Macros <a class="header-anchor" href="#_13-4-macros" aria-label="Permalink to &quot;13.4 Macros&quot;">​</a></h2><p>Procedural macros and arbitrary compile-time execution are intentionally absent. Future syntax-level metaprogramming, if introduced, must preserve the safety model and deterministic expansion.</p><h2 id="_13-5-extern-operations" tabindex="-1">13.5 Extern operations <a class="header-anchor" href="#_13-5-extern-operations" aria-label="Permalink to &quot;13.5 Extern operations&quot;">​</a></h2><p><code>extern</code> is reserved but disabled in the initial language version.</p><p>A future <code>extern op</code> mechanism must be opt-in at compile/materialization time and must clearly separate safe semantic checking from trusted backend plugin execution.</p><h2 id="_13-6-determinism" tabindex="-1">13.6 Determinism <a class="header-anchor" href="#_13-6-determinism" aria-label="Permalink to &quot;13.6 Determinism&quot;">​</a></h2><p>Pure Linnet code is deterministic for a fixed set of inputs under the language&#39;s numeric semantics. Randomness, state, clocks, and external effects require explicit future constructs.</p><h2 id="_13-7-numeric-nondeterminism" tabindex="-1">13.7 Numeric nondeterminism <a class="header-anchor" href="#_13-7-numeric-nondeterminism" aria-label="Permalink to &quot;13.7 Numeric nondeterminism&quot;">​</a></h2><p>Backend parallel reductions may differ in floating-point bit patterns when the selected numeric-equivalence policy allows reassociation or other non-IEEE-exact transformations. Such optimizer policies are outside the source-language semantics and must be explicit compiler options.</p>',17)])])}const h=a(n,[["render",o]]);export{u as __pageData,h as default};
